386: 		client->state = CLIENT_CONNECTING2;
387: 		client->events = POLLOUT; // wait for the result packet to go through
388: 		// no longer need this
389: 		free(client->ib_buf);
390: 		client->ib_buf = NULL;
391: 	} else {
392: 		client->state = CLIENT_COMMAND;
393: 	}
394: 	return 0;
