124: static void reap_dead_devices(void) {
125: 	FOREACH(struct usb_device *usbdev, &device_list) {
126: 		if(!usbdev->alive) {
127: 			device_remove(usbdev);
128: 			usb_disconnect(usbdev);
129: 		}
130: 	} ENDFOREACH
131: }
