72: static char *config_utf16_to_utf8(wchar_t *unistr, long len, long *items_read, long *items_written)
73: {
74: 	if (!unistr || (len <= 0)) return NULL;
75: 	char *outbuf = (char*)malloc(3*(len+1));
76: 	int p = 0;
77: 	int i = 0;
78: 
79: 	wchar_t wc;
80: 
81: 	while (i < len) {
82: 		wc = unistr[i++];
83: 		if (wc >= 0x800) {
84: 			outbuf[p++] = (char)(0xE0 + ((wc >> 12) & 0xF));
85: 			outbuf[p++] = (char)(0x80 + ((wc >> 6) & 0x3F));
86: 			outbuf[p++] = (char)(0x80 + (wc & 0x3F));
87: 		} else if (wc >= 0x80) {
88: 			outbuf[p++] = (char)(0xC0 + ((wc >> 6) & 0x1F));
89: 			outbuf[p++] = (char)(0x80 + (wc & 0x3F));
90: 		} else {
91: 			outbuf[p++] = (char)(wc & 0x7F);
92: 		}
93: 	}
94: 	if (items_read) {
95: 		*items_read = i;
96: 	}
97: 	if (items_written) {
98: 		*items_written = p;
99: 	}
100: 	outbuf[p] = 0;
101: 
102: 	return outbuf;
103: }
104: #endif
